window.ACTIVIDAD = {"id": "ut2-02-swipe-patrones", "titulo": "Swipe de patrones", "subtitulo": "UT2 · Diseño y desarrollo web · 3º EAS Diseño Gráfico", "etiqueta": "UT2 · Diseño y desarrollo web", "objetivo": "Decidir, situación a situación, si un diseño respeta un patrón humano o cuál de dos patrones aprovecha.", "minutos": 15, "preguntasPorIntento": 5, "aprobado": 50, "garantizar": ["deslizar", "deslizar", "deslizar", "vf", "unica"], "diapositivas": {"29": "Patrón exploración segura: nos gusta probar sin miedo a romper nada. Si puedo deshacer o volver atrás, pruebo más y aprendo mejor; si no se puede deshacer, se pide confirmación. Visibilidad, parecido con la vida real y control del usuario (heurísticos de Nielsen).", "30": "Patrón gratificación instantánea: queremos ver resultados rápido. La primera acción debe ser muy fácil y dar acceso inmediato a lo que importa; lo tedioso, después. Ejemplos: Shazam (botón Escuchar), YouTube o TikTok (contenido antes de registrarte).", "31": "Patrón elecciones postergadas: si la tarea es compleja, el usuario puede preferir saltarse un paso y volver más tarde. Las apps deben dejar decidir cuándo completar los detalles poco importantes. Estrategias: no acosar, indicar lo requerido, valores por defecto, permitir volver y experimentar antes del registro.", "33": "Patrón micro-interrupciones: muchas apps están pensadas para momentos cortos (notificaciones, redes, noticias, una partida). Deben ser rápidas, sencillas y ofrecer lo más útil en la primera pantalla.", "34": "Patrón satisficing (satisfactorio y suficiente): no leemos las opciones una por una; elegimos la primera que parece ayudarnos. Llamadas a la acción cortas y claras, diseño ordenado y sencillo, y facilidad para avanzar, retroceder o salir. Ejemplo: Cabify, «Regístrate gratis».", "35": "Patrón cambios sobre la marcha: podemos empezar con un objetivo y cambiarlo sin darnos cuenta. Hay que dejar cambiar de idea, retroceder, salir y recuperar lo que se dejó a medias sin sentirse atrapado. Ejemplo: entro a por un móvil y compro unos auriculares.", "36": "Patrón construcción incremental: al crear algo complejo empezamos por una parte, la probamos, la arreglamos y seguimos con otra. El feedback es imprescindible. Ejemplo: el panel de WordPress.", "37": "Patrón habituación: nos acostumbramos a que ciertas acciones funcionen igual (Ctrl+S, Enter, clic en el logo, gestos para ampliar). La interfaz debe ser predecible para que el usuario se sienta experto.", "39": "Patrón memoria espacial: recordamos dónde está algo por su posición habitual. En barras de herramientas y menús buscamos por «dónde está». Lo importante, al principio o al final; los elementos deben mantener su posición.", "41": "Patrón memoria prospectiva: recordar que tienes que hacer algo en el futuro y hacerlo. Calendarios, alarmas, gestores de tareas, listas de lectura, notas, favoritos. Permitir marcar, guardar, dejar a la vista y retomar por donde se dejó.", "44": "Patrón uso del teclado: no todo el mundo puede o quiere usar ratón o dedo. Atajos, flechas y Mayús en listas, Tab entre campos, flechas, Enter o Espacio en controles, Enter para cerrar diálogos."}, "banco": [{"id": "q01", "tipo": "deslizar", "peso": 5, "enunciado": "¿Este diseño respeta la exploración segura?", "izquierda": "No la respeta", "derecha": "Sí la respeta", "tarjetas": [{"id": "t1", "lado": "d", "texto": "En el editor de vídeo Toma, cada cambio queda en un historial y puedes volver a cualquier paso anterior.", "explicacion": "Poder volver atrás da confianza para probar más funciones."}, {"id": "t2", "lado": "i", "texto": "En la app de notas Apunte, si deslizas una nota se borra para siempre, sin aviso y sin papelera.", "explicacion": "No se puede deshacer y tampoco pide confirmación: da miedo probar."}, {"id": "t3", "lado": "d", "texto": "Al archivar un correo en Buzón, aparece unos segundos el aviso «Correo archivado · Deshacer».", "explicacion": "Muestra qué ha pasado y deja deshacerlo."}, {"id": "t4", "lado": "i", "texto": "En la tienda Lumen, si pulsas «Atrás» durante el pago, se borra todo lo que habías escrito.", "explicacion": "Volver atrás tiene castigo: el usuario no se atreve a moverse."}, {"id": "t5", "lado": "d", "texto": "Antes de vaciar la papelera, la app Nube pregunta: «¿Borrar 12 archivos? No se puede deshacer».", "explicacion": "Si una acción no se puede deshacer, hay que pedir confirmación."}], "explicacion": "Exploración segura: si puedo deshacer o volver atrás, pruebo sin miedo; si algo no se puede deshacer, la app pide confirmación y muestra siempre qué está pasando.", "diapositiva": 29}, {"id": "q02", "tipo": "deslizar", "peso": 5, "enunciado": "¿Este diseño respeta las elecciones postergadas?", "izquierda": "No las respeta", "derecha": "Sí las respeta", "tarjetas": [{"id": "t1", "lado": "i", "texto": "Para ver los horarios del bus en la app Ruta, antes tienes que poner nombre, foto, fecha de nacimiento y gustos.", "explicacion": "Pide lo tedioso antes de dar nada a cambio."}, {"id": "t2", "lado": "d", "texto": "Al registrarte en Pentagrama puedes pulsar «Completar perfil más tarde» y empezar a escuchar música.", "explicacion": "Deja que el usuario decida cuándo completar lo poco importante."}, {"id": "t3", "lado": "i", "texto": "Cada vez que abres la app Brote, una ventana te pide completar tu perfil antes de seguir.", "explicacion": "Acosa al usuario con lo que él había decidido dejar para luego."}, {"id": "t4", "lado": "d", "texto": "El formulario de Viaja Ya llega con idioma y moneda ya elegidos. Puedes cambiarlos luego en Ajustes.", "explicacion": "Valores por defecto razonables y permiso para volver a la información."}, {"id": "t5", "lado": "i", "texto": "La app de lectura Folio te obliga a elegir 10 temas favoritos antes de dejarte leer el primer artículo.", "explicacion": "Obliga a tomar decisiones al principio, cuando aún no le importan."}], "explicacion": "Elecciones postergadas: la app deja saltarse lo complejo o poco importante y volver más tarde. No acosa, usa valores por defecto y permite experimentar antes del registro.", "diapositiva": 31}, {"id": "q03", "tipo": "deslizar", "peso": 5, "enunciado": "¿Este diseño respeta la habituación?", "izquierda": "No la respeta", "derecha": "Sí la respeta", "tarjetas": [{"id": "t1", "lado": "d", "texto": "En la web de la librería Página, pulsar el logo te lleva a la portada.", "explicacion": "Hace lo que esperas por costumbre: el logo lleva al inicio."}, {"id": "t2", "lado": "i", "texto": "En el editor de dibujo Trazo, Ctrl+S no guarda el archivo: abre la ventana de imprimir.", "explicacion": "Rompe un atajo que todo el mundo tiene aprendido."}, {"id": "t3", "lado": "d", "texto": "En la galería Retrato, juntas o separas dos dedos sobre una foto y se amplía.", "explicacion": "Usa un gesto que ya conoces de otras apps."}, {"id": "t4", "lado": "i", "texto": "En el formulario de Agenda Viva, pulsar Enter borra lo escrito en lugar de enviarlo.", "explicacion": "Enter sirve para aceptar o enviar; aquí hace lo contrario."}, {"id": "t5", "lado": "i", "texto": "En la ventana «¿Eliminar archivo?» de Carpeta, los botones están al revés que en el resto de apps.", "explicacion": "Cambia la disposición habitual de los botones de un aviso."}], "explicacion": "Habituación: por costumbre esperamos que ciertas acciones funcionen siempre igual (Ctrl+S, Enter, el logo, los gestos, los botones de un aviso). La interfaz debe ser predecible para que te sientas experto.", "diapositiva": 37}, {"id": "q04", "tipo": "deslizar", "peso": 5, "enunciado": "¿Este diseño ayuda a quien elige rápido la primera opción útil (satisficing)?", "izquierda": "No ayuda", "derecha": "Sí ayuda", "tarjetas": [{"id": "t1", "lado": "d", "texto": "La portada del gimnasio Impulso tiene un solo botón grande: «Reserva tu clase».", "explicacion": "Una llamada a la acción clara: sabes adónde ir sin pensar."}, {"id": "t2", "lado": "i", "texto": "La portada de Cocina Fácil muestra 14 botones iguales, del mismo tamaño y color.", "explicacion": "Nada destaca: hay que leerlo todo y la gente se pierde."}, {"id": "t3", "lado": "i", "texto": "Un botón de la tienda Arena dice «Proceder a la formalización del proceso de adquisición».", "explicacion": "La etiqueta es larga y no se entiende a la primera."}, {"id": "t4", "lado": "d", "texto": "En cada paso de la matrícula de Escuela Nube hay botones claros para «Atrás» y «Salir».", "explicacion": "Facilita retroceder o salir si eliges mal a la primera."}, {"id": "t5", "lado": "d", "texto": "En la app Receta, el botón principal dice «Empezar a cocinar» y destaca sobre el resto.", "explicacion": "Etiqueta corta y bien visible: es la primera opción que parece útil."}], "explicacion": "Satisficing: no leemos todas las opciones; elegimos la primera que parece ayudarnos. Por eso conviene usar etiquetas cortas, un diseño claro y sencillo, y dejar avanzar, retroceder o salir.", "diapositiva": 34}, {"id": "q05", "tipo": "deslizar", "peso": 5, "enunciado": "¿Memoria prospectiva o simplificar la repetición?", "izquierda": "Memoria prospectiva", "derecha": "Simplificar la repetición", "tarjetas": [{"id": "t1", "lado": "i", "texto": "Laura guarda un artículo en «Leer más tarde» para terminarlo esta noche.", "explicacion": "Le ayuda a recordar algo que hará en el futuro."}, {"id": "t2", "lado": "d", "texto": "En el editor de fotos Brillo, Hugo aplica el mismo filtro a 40 fotos con un solo clic.", "explicacion": "Convierte 40 repeticiones en una sola acción."}, {"id": "t3", "lado": "i", "texto": "La app Recado avisa a Pablo el jueves de que tiene que devolver un libro.", "explicacion": "Un recordatorio: es la función típica de la memoria prospectiva."}, {"id": "t4", "lado": "d", "texto": "En el procesador Tinta, Marta cambia «Sevila» por «Sevilla» en todo el documento de una vez.", "explicacion": "Buscar y reemplazar evita corregir palabra por palabra."}, {"id": "t5", "lado": "i", "texto": "Mateo marca un correo con una estrella para responderlo el lunes.", "explicacion": "Marcar algo como pendiente para hacerlo después."}], "explicacion": "Memoria prospectiva (diapositivas 40–42): recordar algo que haremos en el futuro; la app deja marcar, guardar y recibir avisos. Simplificar la repetición (diapositiva 43): si algo se repite mucho, se acorta o se automatiza.", "diapositiva": 41}, {"id": "q06", "tipo": "deslizar", "peso": 5, "enunciado": "¿Gratificación instantánea o construcción incremental?", "izquierda": "Gratificación instantánea", "derecha": "Construcción incremental", "tarjetas": [{"id": "t1", "lado": "i", "texto": "Al abrir la app Oído, el botón «Escuchar» ocupa el centro y reconoce la canción en segundos.", "explicacion": "La primera acción es facilísima y el resultado llega al momento."}, {"id": "t2", "lado": "d", "texto": "En el creador de webs Taller, Elena hace la portada, la previsualiza, la corrige y pasa a la página de contacto.", "explicacion": "Construye algo complejo por partes, probando y corrigiendo."}, {"id": "t3", "lado": "i", "texto": "En la app Clip puedes ver vídeos nada más abrirla. La cuenta solo se pide para comentar.", "explicacion": "Acceso inmediato a lo que importa; lo tedioso, después."}, {"id": "t4", "lado": "d", "texto": "En la app de mapas mentales Rama, Iker añade una idea, ve cómo queda y después la une con otras.", "explicacion": "Empieza por una parte pequeña y luego la relaciona con el resto."}, {"id": "t5", "lado": "d", "texto": "Nerea monta su portafolio en Plantilla: primero una sección, la prueba, y luego añade otra.", "explicacion": "Avanza poco a poco gracias al feedback de cada parte."}], "explicacion": "Gratificación instantánea (diapositiva 30): la primera acción es muy fácil y da resultados rápido. Construcción incremental (diapositiva 36): al crear algo complejo, vamos por partes, probando y corrigiendo; el feedback es imprescindible.", "diapositiva": 30}, {"id": "q07", "tipo": "deslizar", "peso": 5, "enunciado": "¿Micro-interrupciones o social media?", "izquierda": "Micro-interrupciones", "derecha": "Social media", "tarjetas": [{"id": "t1", "lado": "i", "texto": "La app Titular abre en un segundo con las noticias del día, sin pantallas de carga.", "explicacion": "Pensada para un momento corto: rápida y con lo útil en la primera pantalla."}, {"id": "t2", "lado": "d", "texto": "Antes de comprar unas zapatillas, Álex lee las valoraciones con estrellas de otros compradores.", "explicacion": "Busca la opinión de otros para confirmar su decisión."}, {"id": "t3", "lado": "i", "texto": "El juego Burbuja tiene partidas de un minuto y guarda tu puntuación al salir.", "explicacion": "Algo divertido en un rato corto, y retomas cuando vuelvas."}, {"id": "t4", "lado": "d", "texto": "La app Ritmo te deja compartir tu lista de canciones con tus amigos y ver sus comentarios.", "explicacion": "Compartir y comentar con otras personas."}, {"id": "t5", "lado": "d", "texto": "La tienda Pétalo muestra «Quienes compraron esta maceta también compraron…».", "explicacion": "Nos atrae lo que otros compraron junto a ese producto."}], "explicacion": "Micro-interrupciones (diapositiva 33): apps para momentos cortos, rápidas y con lo útil a la vista. Social media (diapositivas 45–46): buscamos opiniones y recomendaciones y queremos compartir y valorar.", "diapositiva": 33}, {"id": "q08", "tipo": "vf", "enunciado": "Si una acción no se puede deshacer, la app debería pedir confirmación antes de hacerla.", "correcta": true, "explicacion": "Verdadero. Es parte de la exploración segura: si puedo deshacer, pruebo sin miedo; si no se puede deshacer, la app pide confirmación.", "diapositiva": 29}, {"id": "q09", "tipo": "vf", "enunciado": "Según el patrón satisficing, el usuario lee todas las opciones antes de elegir la mejor.", "correcta": false, "explicacion": "Falso. No leemos las opciones una por una: miramos rápido y elegimos la primera que parece ayudarnos. Por eso las etiquetas deben ser cortas y claras.", "diapositiva": 34}, {"id": "q10", "tipo": "vf", "enunciado": "Una tienda online que vacía tu carrito cuando sales a mirar otra sección respeta el patrón de cambios sobre la marcha.", "correcta": false, "explicacion": "Falso. Cambios sobre la marcha pide que puedas cambiar de objetivo y recuperar lo que dejaste a medias, como un proceso de compra. Vaciar el carrito te castiga por mirar otra cosa.", "diapositiva": 35}, {"id": "q11", "tipo": "unica", "enunciado": "Rocío no puede usar el ratón. Para apuntarse a un curso en la web de Escuela Nube, ¿qué patrón debe tener en cuenta el formulario?", "opciones": [{"id": "te", "texto": "Uso del teclado", "correcta": true}, {"id": "me", "texto": "Memoria espacial"}, {"id": "mi", "texto": "Micro-interrupciones"}, {"id": "gi", "texto": "Gratificación instantánea"}], "explicacion": "Uso del teclado: no todo el mundo puede o quiere usar ratón o dedo. El formulario debe dejar pasar de campo en campo con Tab y marcar opciones con flechas, Enter o Espacio.", "diapositiva": 44}, {"id": "q12", "tipo": "unica", "enunciado": "En el editor Lienzo, los botones de la barra de herramientas cambian de orden cada vez que abres un archivo. ¿Qué patrón rompe?", "opciones": [{"id": "me", "texto": "Memoria espacial", "correcta": true}, {"id": "mp", "texto": "Memoria prospectiva"}, {"id": "ci", "texto": "Construcción incremental"}, {"id": "ep", "texto": "Elecciones postergadas"}], "explicacion": "Memoria espacial: en barras de herramientas y menús encontramos las cosas por dónde están. Los elementos deben mantener su posición. La memoria prospectiva trata de recordar tareas futuras, no posiciones.", "diapositiva": 39}, {"id": "q13", "tipo": "unica", "enunciado": "Según el patrón de construcción incremental, ¿qué es imprescindible en una herramienta para crear webs por partes?", "opciones": [{"id": "fb", "texto": "El feedback para probar y corregir cada parte.", "correcta": true}, {"id": "rg", "texto": "Un registro completo antes de empezar la primera página."}, {"id": "or", "texto": "Un orden fijo de pasos que no se puede cambiar."}, {"id": "va", "texto": "Las valoraciones de otras personas sobre cada página."}], "explicacion": "Construcción incremental: empezamos por una parte pequeña, la probamos, la arreglamos y seguimos con otra. Para eso el feedback es imprescindible. No hay un orden fijo: cada persona avanza a su manera.", "diapositiva": 36}]};
